	 */
	public $breadcrumbs=array();
	public function beforeAction($action)
	{
		$controller = $this->id;
		$currentAction = $action->id;

		if ($controller === 'site' && $currentAction === 'login' && !empty(Yii::app()->user->partner_slug)) {
			$this->redirect('/' . rtrim(Yii::app()->user->partner_slug, '/'));
			return false;
		}
		if ($controller === 'site' && $currentAction === 'login') {
			return parent::beforeAction($action);
		}

		
		if (!isset($_GET['partner_slug']) || empty($_GET['partner_slug'])) {
			return parent::beforeAction($action);
		}

		$user_exist = DndAdmin::model()->findByPk(Yii::app()->user->user_id);
		if ($user_exist == null) 
		{
			Yii::app()->user->logout();
			Yii::app()->session->destroy();
			$this->redirect(Yii::app()->homeUrl); 
			return false;
		}
		if (empty(Yii::app()->user->partner_slug)) {
			Yii::app()->user->logout();
			Yii::app()->session->destroy();
			$this->redirect(Yii::app()->homeUrl); 
			return false;
		}

		return parent::beforeAction($action);
	}	
