	public function softdata($term)
	{	
		if(!empty($term))
		{
			$sql="SELECT software_id as id ,soft_name as text FROM software_reg  WHERE soft_name LIKE '$term%' AND approved_status=1 ";
			$result=Yii::app()->db->createCommand($sql)->queryAll();
			return json_encode($result);
		}	
	}
	public function Partenerallvendorslug()
	{	
		if(!empty(Yii::app()->user->is_admin) && Yii::app()->user->is_admin == 1)
		{
			$result=Yii::app()->db->createCommand("SELECT slug FROM partner_masters group by slug")->queryAll();
			return $result;
		}	
	}
